condition:
const terms = get(ctx.entry, 'terms', {});
return get(ctx.entry, 'status', 'DRAFT') !== 'DRAFT' &&
	get(terms, 'probation_period', null) !== null;

validate:
const terms = get(ctx.entry, 'terms', {});
const probation = get(terms, 'probation_period', null);
const end = get(probation, 'to', null);
return end !== null && end <= add_months(probation.from, ctx.lookup.maximum_months);

condition:
const role = get(ctx.entry, 'engagement', null);
return get(ctx.entry, 'status', 'DRAFT') !== 'DRAFT' &&
	(role === 'INTERN' || role === 'APPRENTICE');

validate:
const role = get(ctx.entry, 'engagement', null);
const program = get(get(ctx.entry, 'employee_extension_data', {}), 'ebet_program', null);
return role === 'APPRENTICE'
	? program === ctx.lookup.apprenticeship_program
	: ctx.lookup.trainee_programs.includes(program);

const extension = get(ctx.entry, 'employee_extension_data', {});
const place = get(extension, 'wage_payment_place', null);
return place !== ctx.lookup.prohibited_place ||
	get(extension, 'employed_at_payment_place', false) === true;

const terms = get(ctx.entry, 'terms', null);
if (terms === null) return false;
return ctx.lookup.statutory_work_categories.includes(get(terms, 'statutory_work_category', null)) &&
	ctx.lookup.residency_statuses.includes(get(terms, 'residency_status', null));

const due = get(ctx.entry, 'final_pay_due_on', null);
const end = get(get(ctx.entry, 'effective_range', {}), 'to', null);
if (end === null) return false;
if (!(due >= end)) return false;
return due <= add_days(end, ctx.lookup.final_pay_maximum_days);

const inputs = get(ctx.entry, 'inputs', {});
const year = get(inputs, 'tax_year', null);
const payment = get(inputs, 'compensation_payment_case_id', '');
if (year === null) return false;
if (!(year >= ctx.lookup.minimum_year)) return false;
return String(payment).trim() !== '';

const employer = get(ctx.subject, 'employer.entity_extension_data', {});
if (get(employer, 'bmbe_certificate_of_authority', false) === true) return true;
if (get(employer, 'minimum_wage_exemption_approved', false) === true) return true;
const terms = get(ctx.entry, 'terms', {});
const facts = get(ctx.subject, 'employment.employee_extension_data', {});
const domestic = get(terms, 'statutory_work_category', '') === 'DOMESTIC';
const region = get(facts, 'work_region', get(employer, 'region', ''));
if (region === '') return true;
const table = domestic ? ctx.lookup.minimum_wage_domestic : ctx.lookup.minimum_wage_by_region;
const start = get(ctx.entry, 'effective_range.from', '9999-12-31');
const rates = table.filter((entry) => entry.region === region && entry.from <= start);
if (rates.length === 0) return false;
const floor = Number(rates.toSorted((a, b) => (a.from < b.from ? 1 : -1))[0].monthly);
const rate = get(terms, 'rate', {});
const amount = Number(get(rate, 'amount', 0));
const unit = get(rate, 'unit', 'MONTHLY');
if (domestic && unit === 'MONTHLY') return amount + 0.005 >= floor;
const hours = Number(get(terms, 'normal_hours_per_day', 0));
// DOLE ch.2: a day is the monthly wage × 12 ÷ the contract week's working days (365 − 52 rest days).
const daysPerYear = 365 - 52 * (7 - Number(get(terms, 'normal_days_per_week', 6)));
const daily = unit === 'DAILY'
	? amount
	: unit === 'HOURLY'
		? amount * hours
		: (amount * 12) / daysPerYear;
return daily + 0.005 >= (floor * 12) / daysPerYear;

// js
const item = first(ctx.reads.leave_catalog);
if (item == null || !ctx.lookup.no_pay.includes(item.code)) return true;
const employer = ctx.subject.employer;
const cutoff = Number(get(employer, 'pay_cutoff_day', 1));
const halves = get(employer, 'payment_schedule.frequency', 'MONTHLY') === 'SEMI_MONTHLY';
const shifted = (month, by) => add_months(month + '-01', by).slice(0, 7);
const periodOf = (date) => {
	const month = date.slice(0, 7);
	const dayOf = Number(date.slice(8, 10));
	const part = dayOf <= 15 ? 1 : 2;
	if (!halves) return cutoff > 1 && dayOf >= cutoff ? shifted(month, 1) : month;
	if (cutoff <= 1) return month + '-' + part;
	return part === 1 ? month + '-2' : shifted(month, 1) + '-1';
};
const dates = ctx.entry.days.map((day) => day.date);
if (get(ctx.entry, 'reverses', null) != null && ctx.reads.leave_catalog_entry.some((row) => row.days.some((day) => dates.includes(day.date))))
	throw 'That day has not been paid yet. Delete the entry instead of reversing it.';
const ran = ctx.reads.payroll_run.map((run) => run.period);
const closed = ctx.entry.days.find((day) => ran.includes(periodOf(day.date)));
if (closed != null)
	throw closed.date + ' is in a period that has already run. Date this entry in the next period to run, and that run takes it.';
return true;

// js
const form = first(ctx.reads.workplace_case_catalog);
const inputs = get(ctx.entry, 'inputs', {});
const missing = get(form, 'lookup.input_schema.required', []).filter((key) => get(inputs, key, '') === '');
if (missing.length > 0) throw 'This case needs ' + missing.join(', ') + '.';
return true;
